// DATA — 1. Simple stat tile
// Modeled on: UniversalMetricCard.kt:59-163, DashboardScreen.kt's AssetCard (non-sparkline path)
// ============================================================================

@Composable
private fun DataStatTileSample() {
    val pulseColors = LocalPulseColors.current
    PulseCard(style = PulseCardStyle.DATA, onClick = {}, modifier = Modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "VIX",
                    style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                    color = MaterialTheme.colorScheme.onSurface
                )
                Icon(
                    painter = painterResource(id = R.drawable.ic_chevron_forward),
                    contentDescription = null,
                    tint = pulseColors.onSurfaceMuted,
                    modifier = Modifier.size(dimensionResource(id = R.dimen.icon_size_small))
                )
            }
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
            Text(
                "14.82",
                style = MaterialTheme.typography.headlineSmall.copy(fontWeight = FontWeight.Bold),
                color = MaterialTheme.colorScheme.onSurface
            )
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))
            // 💡 VIX inverts signal semantics on purpose -- a rising VIX is bearish for equities
            // even though the number itself went up, same reasoning DirectionalChangePill's own
            // doc comment gives for decoupling `direction` from `pillColor`.
            DirectionalChangePill(
                changeText = "3.2%",
                direction = ChangeDirection.UP,
                pillColor = pulseColors.signalBearishPill,
                contentColor = pulseColors.signalBearishText
            )
        }
    }
}

